using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;
    vector<int> a(n);
    for (int &x : a) cin >> x;

    if (k < 0 || k >= n) {
        cout << "INVALID\n";
        return 0;
    }

    // Use 64-bit integers to prevent overflow
    long long sum = 0;
    // Monotonic deques for O(1) push/pop and O(n) total operations
    deque<int> dq;
    deque<int> dq_min;
    deque<int> dq_max;

    for (int i = 0; i < k; ++i) {
        sum += a[i];
        int val = a[i];
        // Push to main deque
        dq.push_front(val);
        // Push to min deque: remove elements not greater than val
        while (dq_min.size() < dq.size()) {
            dq_min.push_front(val);
            dq_min.pop_back();
        }
        // Push to max deque: remove elements not less than val
        while (dq_max.size() < dq.size()) {
            dq_max.push_front(val);
            dq_max.pop_back();
        }
    }

    for (int left = 0; left + k < n; ++left) {
        cout << sum << ' ' << dq_min[0] << ' ' << dq_max[0] << '\n';
        sum -= a[left];
        sum += a[left + k];
        // Remove the leftmost element from all deques
        dq.pop_back();
        while (dq_min.size() > dq.size()) {
            dq_min.pop_back();
        }
        while (dq_max.size() > dq.size()) {
            dq_max.pop_back();
        }
    }
}
